Steps:
[AUTH role=USER]
[GQL-OP find_orders]
  query {
    orders(first: 20, filter: "status:Completed") {
      items { number items { productId name } }
    }
  }
[GQL-EXEC find_orders]
[GQL-CAPTURE find_orders.data.orders.items.0.items.0.productId → PID]
[GQL-OP can_fb]
  query { canLeaveFeedback(storeId: "{{STORE_ID}}" entityId: "{{PID}}" entityType: "Product") }
[GQL-EXEC can_fb]
[GQL-OP create]
  mutation {
    createReview(command: {
      storeId: "{{STORE_ID}}"
      entityId: "{{PID}}"
      entityType: "Product"
      review: "AGENT-TEST solid product, works as described."
      rating: 5
    }) { id userName validationErrors { errorCode errorMessage } }
  }
[GQL-EXEC create]
[GQL-CAPTURE create.data.createReview.id → NEW_REVIEW_ID]

[AUTH role=USER]
[GQL-OP find_orders]
  query { orders(first: 5, filter: "status:Completed") { items { items { productId } } } }
[GQL-EXEC find_orders]
[GQL-CAPTURE find_orders.data.orders.items.0.items.0.productId → PID]
[GQL-OP create_vendor]
  mutation {
    createReview(command: { storeId: "{{STORE_ID}}" entityId: "{{PID}}" entityType: "Vendor" review: "AGENT-TEST vendor review" rating: 4 })
    { id validationErrors { errorCode errorMessage } }
  }
[GQL-EXEC create_vendor]

[AUTH role=USER]
[GQL-OP any_product]
  query { products(storeId: "{{STORE_ID}}" first: 5) { items { id name } } }
[GQL-EXEC any_product]
[GQL-CAPTURE any_product.data.products.items.0.id → UNBOUGHT_PID]
[GQL-OP create_noorder]
  mutation {
    createReview(command: { storeId: "{{STORE_ID}}" entityId: "{{UNBOUGHT_PID}}" entityType: "Product" review: "AGENT-TEST not purchased" rating: 3 })
    { id validationErrors { errorCode errorMessage } }
  }
[GQL-EXEC create_noorder]

[AUTH role=USER]
[GQL-OP find_orders]
  query { orders(first: 20, filter: "status:Completed") { items { items { productId } } } }
[GQL-EXEC find_orders]
[GQL-CAPTURE find_orders.data.orders.items.0.items.0.productId → PID]
[GQL-OP create_imgs]
  mutation { createReview(command: {
      storeId: "{{STORE_ID}}" entityId: "{{PID}}" entityType: "Product" review: "AGENT-TEST too many images" rating: 4
      imageUrls: ["/api/files/a", "/api/files/b", "/api/files/c", "/api/files/d", "/api/files/e", "/api/files/f"]
    }) { id validationErrors { errorCode errorMessage } } }
[GQL-EXEC create_imgs]

[GQL-OP read]
  query { customerReviews(storeId: "{{STORE_ID}}" entityId: "@td(REVIEW_PRODUCT.id)" entityType: "Product" first: 20) {
      totalCount items { id userName title review rating createdDate } } }
[GQL-EXEC read]

[GQL-OP page1]
  query { customerReviews(storeId: "{{STORE_ID}}" entityId: "@td(REVIEW_PRODUCT.id)" entityType: "Product" first: 5) { totalCount items { id } pageInfo { hasNextPage endCursor } } }
[GQL-EXEC page1]
[GQL-OP page2]
  query { customerReviews(storeId: "{{STORE_ID}}" entityId: "@td(REVIEW_PRODUCT.id)" entityType: "Product" first: 5 after: "5") { totalCount items { id } } }
[GQL-EXEC page2]

[GQL-OP sorted]
  query { customerReviews(storeId: "{{STORE_ID}}" entityId: "@td(REVIEW_PRODUCT.id)" entityType: "Product" first: 10 sort: "createddate:desc") { totalCount items { id createdDate } } }
[GQL-EXEC sorted]

[GQL-OP empty_read]
  query { customerReviews(storeId: "{{STORE_ID}}" entityId: "{{bogus_entity}}" entityType: "Product" first: 5) { totalCount items { id } } }
[GQL-EXEC empty_read]
